function [cr, cv] = fix_counts(r, v, s)
%FIX_COUNTS  The GNSS fix, position r and velocity v (ECEF), as its frame's counts.
%   r: real[m][3] (passed in m)
%   v: real[m/s][3] (passed in m/s)
%   s: EmuScale (passed rec)
%   returns cr: int[3] (passed a whole number)
%   returns cv: int[3] (passed a whole number)
%   Generated by tools/pcode.py from the pseudocode (trinetra-pcode/2); do not edit.
    cr = zeros(3, 1);
    cv = zeros(3, 1);
    cr = zeros(3, 1);
    cv = zeros(3, 1);
    for i = (0):((3) - 1)
        cr((i) + 1) = asils.models.emucodec.emu_count((r((i) + 1) / s.pos), s.lo32, s.hi32);
        cv((i) + 1) = asils.models.emucodec.emu_count((v((i) + 1) / s.vel), s.lo32, s.hi32);
    end
end
